async function seed() {
  try {
    await mongoose.connect(MONGO_URI);
    console.log('✅ Connected to MongoDB:', MONGO_URI);

    // Clear existing data
    await Job.deleteMany({});
    console.log('🗑️  Cleared existing jobs');

    // Build all jobs array
    const allJobs = [
      ...CODE_JOBS.map(j => ({ ...j, industry: 'Code', status: rand(STATUSES), scrapedAt: scrapedDaysAgo(Math.floor(Math.random() * 10)) })),
      ...DATA_JOBS.map(j => ({ ...j, industry: 'Data Analysis', status: rand(STATUSES), scrapedAt: scrapedDaysAgo(Math.floor(Math.random() * 10)) })),
      ...BA_JOBS.map(j => ({ ...j, industry: 'Business Analysis', status: rand(STATUSES), scrapedAt: scrapedDaysAgo(Math.floor(Math.random() * 10)) })),
    ].map(j => ({
      ...j,
      companyLogo: '',
      website: j.website || `https://${j.companyName.toLowerCase().replace(/\s/g,'-')}.com`,
    }));

    const result = await Job.insertMany(allJobs, { ordered: false });
    console.log(`✅ Inserted ${result.length} jobs`);
    console.log(`   📦 Code:             ${CODE_JOBS.length}`);
    console.log(`   📊 Data Analysis:    ${DATA_JOBS.length}`);
    console.log(`   📋 Business Analysis: ${BA_JOBS.length}`);

    // Seed students
    const { Student } = require('../models/Student') || { Student: require('../models/Student') };
    await Student.deleteMany({});
    await Student.insertMany(STUDENTS);
    console.log(`✅ Inserted ${STUDENTS.length} students`);

    console.log('\n🎉 Seed completed successfully!');
    process.exit(0);
  } catch (err) {
    console.error('❌ Seed failed:', err.message);
    process.exit(1);
  }
}

seed();
